const DEFAULT_ROLE_DEF = {
  highPriority: ['Problem Solving', 'Git', 'Core Technical Skills', 'Documentation'],
  mediumPriority: ['Database Management', 'System Design'],
  lowPriority: ['Testing', 'Deployment Automation'],
  reasons: {
    'Problem Solving': 'Crucial for analyzing technical problems and crafting robust solutions.',
    'Git': 'Essential version control mechanism for team collaboration.',
    'Core Technical Skills': 'Fundamental competencies required for fulfilling role objectives.',
    'Documentation': 'Communicates technical design and instructions clearly.',
    'Database Management': 'Required for interacting with persistent data layers.',
    'System Design': 'Ensures maintainable and decoupled architecture.',
    'Testing': 'Validates software correctness and guards against regressions.',
    'Deployment Automation': 'Reduces human error during application delivery.',
  },
};

/**
 * Perform rule-based resume analysis matching the 100-point rubric
 */
const runFallbackAnalysis = (resumeData, targetRole, jobDescription, rawText = '') => {
  const roleName = targetRole ? targetRole.trim() : 'Software Developer';
  const roleDef = ROLE_DEFINITIONS[roleName] || DEFAULT_ROLE_DEF;

  const parsed = resumeData.parsedData || resumeData;
  const personalInfo = parsed.personalInfo || {};
  const skillsObj = parsed.skills || {};
  const education = Array.isArray(parsed.education) ? parsed.education : [];
  const projects = Array.isArray(parsed.projects) ? parsed.projects : [];
  const experience = Array.isArray(parsed.experience) ? parsed.experience : [];
  const certifications = Array.isArray(parsed.certifications) ? parsed.certifications : [];
  const fullText = rawText || resumeData.rawText || '';

  // Extract skills
  const progLangs = (skillsObj.programmingLanguages || []).map((s) => s.trim()).filter(Boolean);
  const frameworks = (skillsObj.frameworks || []).map((s) => s.trim()).filter(Boolean);
  const databases = (skillsObj.databases || []).map((s) => s.trim()).filter(Boolean);
  const tools = (skillsObj.tools || []).map((s) => s.trim()).filter(Boolean);
  const other = (skillsObj.other || []).map((s) => s.trim()).filter(Boolean);

  const allSkillsSet = new Set(
    [...progLangs, ...frameworks, ...databases, ...tools, ...other].map((s) => s.toLowerCase())
  );
  const existingSkills = [...new Set([...progLangs, ...frameworks, ...databases, ...tools, ...other])];

  // 1. Technical Skills Score (max 25)
  const missingSkills = [];
  let matchedPoints = 0;
  let totalRolePoints = 0;

  // High priority check
  roleDef.highPriority.forEach((s) => {
    totalRolePoints += 3;
    if (allSkillsSet.has(s.toLowerCase())) {
      matchedPoints += 3;
    } else {
      missingSkills.push({
        skill: s,
        priority: 'High',
        reason: roleDef.reasons[s] || 'Core competency expected for this career track.',
      });
    }
  });

  // Medium priority check
  roleDef.mediumPriority.forEach((s) => {
    totalRolePoints += 2;
    if (allSkillsSet.has(s.toLowerCase())) {
      matchedPoints += 2;
    } else {
      missingSkills.push({
        skill: s,
        priority: 'Medium',
        reason: roleDef.reasons[s] || 'Important technology widely utilized in modern workflows.',
      });
    }
  });

  // Low priority check
  roleDef.lowPriority.forEach((s) => {
    totalRolePoints += 1;
    if (allSkillsSet.has(s.toLowerCase())) {
      matchedPoints += 1;
    } else {
      missingSkills.push({
        skill: s,
        priority: 'Low',
        reason: roleDef.reasons[s] || 'Supplementary skill that increases candidate versatility.',
      });
    }
  });

  const relevancePct = totalRolePoints > 0 ? Math.min(100, Math.round((matchedPoints / totalRolePoints) * 100)) : 50;
  const breadthScore = Math.min(10, existingSkills.length * 1.2);
  const roleMatchScore = (relevancePct / 100) * 15;
  const technicalScore = Math.min(25, Math.max(3, Math.round((breadthScore + roleMatchScore) * 10) / 10));

  // 2. Projects Score (max 20)
  const projectAnalysis = [];
  let projRawScore = 0;

  if (projects.length === 0) {
    projRawScore = 3;
  } else {
    projects.forEach((p) => {
      const title = p.title || 'Technical Project';
      const tech = Array.isArray(p.technologies) ? p.technologies : [];
      const desc = p.description || '';
      const hasMetrics = /\b\d+%(?: reduction| increase)?|\b\d+\s*(?:ms|users|requests|qps)\b/i.test(desc);
      const isHighRel = tech.some((t) => roleDef.highPriority.some((hp) => hp.toLowerCase() === t.toLowerCase()));

      let rel = 'Medium';
      let itemScore = 6;
      if (isHighRel || tech.length >= 3) {
        rel = 'High';
        itemScore = 8;
      } else if (tech.length === 0) {
        rel = 'Low';
        itemScore = 4;
      }

      if (hasMetrics) itemScore += 2;
      if (p.link) itemScore += 1;

      projectAnalysis.push({
        title,
        technologies: tech,
        relevance: rel,
        feedback: `${rel} relevance for ${roleName}. Stack: ${tech.join(', ') || 'General'}.`,
        suggestions: hasMetrics
          ? 'Clear technical scope and metrics demonstrated.'
          : 'Add quantifiable outcomes (e.g. latency reduced by 30%, user load handled).',
      });

      projRawScore += itemScore;
    });
  }

  const projMultiplier = Math.min(1.0, projects.length / 2.0);
  const projectsScore = projects.length === 0
    ? 3.0
    : Math.min(20, Math.max(4, Math.round((projRawScore / Math.max(1, projects.length)) * 1.5 * projMultiplier * 10) / 10));

  // 3. Work Experience Score (max 20)
  const hasExp = experience.length > 0;
  let expScore = 7.0;
  let expLevel = 'Academic / Student';
  let expSummary = 'No formal corporate work experience or internships currently listed.';
  let expFeedback = 'For emerging talent and students, academic projects and open-source contributions represent core proof of ability.';
  let expSuggestions = 'Pursue virtual internships, open-source pull requests, or technical hackathons to offset formal commercial tenure.';

  if (hasExp) {
    const isInternship = experience.some((e) => /intern|apprentice/i.test(e.position || ''));
    if (experience.length >= 2 && !isInternship) {
      expLevel = 'Junior to Mid';
      expScore = 15.5;
    } else {
      expLevel = isInternship ? 'Intern / Entry-level' : 'Junior';
      expScore = 12.5;
    }
    expSummary = `Recorded ${experience.length} professional experience / internship position(s) at ${expLevel} level.`;
    expFeedback = `Demonstrates commercial exposure. Roles: ${experience.map((e) => e.position || 'Engineer').join(', ')}.`;
    expSuggestions = "Follow the Google X-Y-Z formula for bullet points: 'Accomplished [X] measured by [Y] by doing [Z]'.";
  }

  // 4. Education Score (max 10)
  let eduScore = 4.0;
  let eduFeedback = 'Academic credentials cataloged.';
  if (education.length > 0) {
    eduScore = 7.5;
    const hasCs = education.some((e) => /computer|engineering|science|technology|b\.tech|bca|mca/i.test(e.degree || ''));
    if (hasCs) eduScore += 2.0;
    eduScore = Math.min(10, eduScore);
    eduFeedback = `Verified academic qualification: ${education.map((e) => e.degree || 'Degree').join(', ')}.`;
  } else {
    eduFeedback = 'No degree credentials listed. Educational background should be clearly documented.';
  }

  // 5. Certifications Score (max 10)
  let certScore = 3.0;
  let certFeedback = 'No professional industry certifications detected.';
  if (certifications.length > 0) {
    certScore = Math.min(10, 6.0 + certifications.length * 2.0);
    certFeedback = `Cataloged ${certifications.length} credential(s): ${certifications.map((c) => c.name || 'Cert').join(', ')}.`;
  }

  // 6. Resume Quality & Completeness (max 15)
  let compScore = 4.0;
  if (personalInfo.email) compScore += 1.5;
  if (personalInfo.phone) compScore += 1.5;
  if (personalInfo.location) compScore += 1.0;
  if (personalInfo.linkedin || personalInfo.github) compScore += 2.0;
  if (existingSkills.length >= 4) compScore += 2.0;
  if (projects.length >= 1) compScore += 1.5;
  if (education.length >= 1) compScore += 1.5;

  const wordCount = fullText.split(/\s+/).filter(Boolean).length;
  if (wordCount >= 200 && wordCount <= 900) compScore += 2.0;
  compScore = Math.min(15, Math.max(4, Math.round(compScore * 10) / 10));

  // Compute Overall Score (0-100)
  const totalScore = technicalScore + projectsScore + expScore + eduScore + certScore + compScore;
  const overallScore = Math.min(100, Math.max(0, Math.round(totalScore)));

  // Strengths and Weaknesses
  const strengths = [];
  const weaknesses = [];

  if (technicalScore >= 16) {
    strengths.push(`Strong repertoire of ${existingSkills.length} technical skills aligned with modern stacks.`);
  }
  if (projects.length >= 2) {
    strengths.push(`Portfolio of ${projects.length} technical projects demonstrating implementation initiative.`);
  }
  if (hasExp) {
    strengths.push('Verifiable commercial or internship experience demonstrating team collaboration.');
  } else {
    strengths.push('Academic focus and foundational competencies aligned with target role.');
  }
  if (certScore >= 7) {
    strengths.push('Holds industry-recognized credentials verifying domain commitment.');
  }
  if (compScore >= 11) {
    strengths.push('Well-structured document with clear contact details and delineated sections.');
  }
  if (strengths.length < 2) {
    strengths.push(`Clear intent toward pursuing a career as a ${roleName}.`);
  }

  const highMissing = missingSkills.filter((m) => m.priority === 'High');
  if (highMissing.length > 0) {
    weaknesses.push(`Missing critical core skills for ${roleName}: ${highMissing.slice(0, 3).map((m) => m.skill).join(', ')}.`);
  }
  if (!hasExp) {
    weaknesses.push('Lack of formal commercial work experience or technical internships.');
  }
  if (projects.length === 0) {
    weaknesses.push('Absence of dedicated technical projects showcasing practical implementation.');
  } else {
    weaknesses.push('Project bullet points lack quantified impact metrics and production deployment links.');
  }
  if (certScore < 5) {
    weaknesses.push('No recognized cloud or professional industry certifications listed.');
  }

  // Actionable Suggestions
  const improvementSuggestions = [
    `Bridge top skill gaps by building a focused project with ${highMissing.slice(0, 2).map((m) => m.skill).join(' and ') || 'relevant tools'}.`,
    'Include quantifiable numbers in project bullet points (e.g., latency reduction %, daily active users, requests/sec).',
    hasExp
      ? 'Frame work achievements using the Google X-Y-Z formula to demonstrate business impact.'
      : 'Contribute to open-source repositories on GitHub to build collaborative version-controlled experience.',
    'Include live deployment links and comprehensive README documentation for featured projects.',
    'Consider preparing for a foundational cloud certification (e.g., AWS Certified Cloud Practitioner) to validate skills.',
  ];

  // AI Feedback
  const aiFeedback = {
    summary: `Resume demonstrates a solid baseline score of ${overallScore}/100 with clear potential for ${roleName} roles.`,
    roleSuitability: overallScore >= 70
      ? `Strong contender for Junior to Mid-Level ${roleName} roles.`
      : `Developing candidate for ${roleName}; targeted skill acquisition will boost callback rates.`,
    mainImprovements: `Prioritize acquiring ${highMissing.slice(0, 2).map((m) => m.skill).join(' and ') || 'core tools'} and add quantifiable metrics to projects.`,
    nextSteps: `Build an end-to-end project incorporating ${highMissing[0]?.skill || 'the target stack'} and deploy it publicly on the cloud.`,
  };

  return {
    targetRole: roleName,
    jobDescription: jobDescription || null,
    overallScore,
    categoryScores: {
      technicalSkills: {
        score: technicalScore,
        maxScore: 25.0,
        feedback: `${existingSkills.length} skills identified with ${relevancePct}% role alignment.`,
      },
      projects: {
        score: projectsScore,
        maxScore: 20.0,
        feedback: `${projects.length} project(s) analyzed for relevance and depth.`,
      },
      experience: {
        score: expScore,
        maxScore: 20.0,
        feedback: expFeedback,
      },
      education: {
        score: eduScore,
        maxScore: 10.0,
        feedback: eduFeedback,
      },
      certifications: {
        score: certScore,
        maxScore: 10.0,
        feedback: certFeedback,
      },
      completeness: {
        score: compScore,
        maxScore: 15.0,
        feedback: 'Structural balance, section breadth, and contact information evaluated.',
      },
    },
    strengths: strengths.slice(0, 5),
    weaknesses: weaknesses.slice(0, 5),
    technicalSkillsAnalysis: {
      existingSkills,
      categorized: {
        programmingLanguages: progLangs,
        frameworks,
        databases,
        tools,
        other,
      },
      roleRelevanceScore: relevancePct,
      summary: `Cataloged ${existingSkills.length} technical skills with ${relevancePct}% relevance to ${roleName}.`,
    },
    missingSkills,
    projectAnalysis,
    experienceAnalysis: {
      hasExperience: hasExp,
      level: expLevel,
      summary: expSummary,
      feedback: expFeedback,
      suggestions: expSuggestions,
    },
    improvementSuggestions,
    aiFeedback,
    analysisProvider: 'rule-based-fallback',
  };
};

module.exports = {
  runFallbackAnalysis,
  ROLE_DEFINITIONS,
};
